import json
import re

todos = []
next_id = 1

def handle(method: str, path: str, body: bytes) -> tuple[int, dict]:
    global todos, next_id

    if path == "/todos":
        if method == "GET":
            return 200, {"items": todos}

        elif method == "POST":
            try:
                data = json.loads(body.decode())
                title = data.get("title", "")
                if not title:
                    return 400, {"error": "標題不能為空"}

                new_todo = {
                    "id": str(next_id),
                    "title": title,
                    "completed": False
                }
                todos.append(new_todo)
                next_id += 1
                return 200, new_todo
            except json.JSONDecodeError:
                return 400, {"error": "無效的JSON格式"}

        else:
            return 405, {"error": "不支援的方法"}

    elif path.startswith("/todos/"):
        todo_id = re.match(r"/todos/([0-9]+)", path).group(1)

        # 找到對應的待辦事項
        todo_index = None
        for i, todo in enumerate(todos):
            if todo["id"] == todo_id:
                todo_index = i
                break

        if todo_index is None:
            return 404, {"error": "待辦事項不存在"}

        if method == "PUT":
            try:
                data = json.loads(body.decode())
                completed = data.get("completed", False)

                todos[todo_index]["completed"] = completed
                return 200, todos[todo_index]
            except json.JSONDecodeError:
                return 400, {"error": "無效的JSON格式"}

        elif method == "DELETE":
            del todos[todo_index]
            return 200, {"message": "待辦事項已刪除"}

        else:
            return 405, {"error": "不支援的方法"}

    else:
        return 404, {"error": "找不到路徑"}

