document.addEventListener('DOMContentLoaded', () => {
  const todoInput = document.getElementById('todo-input');
  const addBtn = document.getElementById('add-btn');
  const todoList = document.getElementById('todo-list');
  const remainingCount = document.getElementById('remaining-count');
  const errorMessage = document.getElementById('error-message');

  // 預設待辦事項列表
  let todos = [];

  // 顯示錯誤訊息
  function showError(message) {
    errorMessage.textContent = message;
    setTimeout(() => {
      errorMessage.textContent = '';
    }, 3000);
  }

  // 更新未完成待辦數量
  function updateRemainingCount() {
    const count = todos.filter(todo => !todo.completed).length;
    remainingCount.textContent = count;
  }

  // 建立待辦事項項目
  function createTodoElement(todo) {
    const li = document.createElement('li');
    li.className = 'todo-item';
    li.dataset.id = todo.id;

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = todo.completed;

    const span = document.createElement('span');
    span.textContent = todo.title;
    span.className = todo.completed ? 'completed' : '';

    const deleteBtn = document.createElement('button');
    deleteBtn.textContent = '刪除';
    deleteBtn.className = 'delete-btn';

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(deleteBtn);

    // 綁定事件處理
    checkbox.addEventListener('change', () => {
      updateTodoStatus(todo.id, checkbox.checked);
    });

    deleteBtn.addEventListener('click', () => {
      deleteTodo(todo.id);
    });

    return li;
  }

  // 渲染待辦事項列表
  function renderTodos() {
    todoList.innerHTML = '';
    todos.forEach(todo => {
      const todoElement = createTodoElement(todo);
      todoList.appendChild(todoElement);
    });
    updateRemainingCount();
  }

  // 新增待辦事項
  async function addTodo() {
    const title = todoInput.value.trim();
    if (!title) return;

    try {
      const response = await fetch('api/todos', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ title })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || '新增待辦事項失敗');
      }

      const newTodo = await response.json();
      todos.push(newTodo);
      renderTodos();
      todoInput.value = '';
    } catch (error) {
      showError(error.message);
    }
  }

  // 更新待辦事項狀態
  async function updateTodoStatus(id, completed) {
    try {
      const response = await fetch(`api/todos/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ completed })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || '更新待辦事項狀態失敗');
      }

      const updatedTodo = await response.json();
      const todoIndex = todos.findIndex(todo => todo.id === id);
      if (todoIndex !== -1) {
        todos[todoIndex] = updatedTodo;
        renderTodos();
      }
    } catch (error) {
      showError(error.message);
    }
  }

  // 刪除待辦事項
  async function deleteTodo(id) {
    try {
      const response = await fetch(`api/todos/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || '刪除待辦事項失敗');
      }

      todos = todos.filter(todo => todo.id !== id);
      renderTodos();
    } catch (error) {
      showError(error.message);
    }
  }

  // 獲取所有待辦事項
  async function fetchTodos() {
    try {
      const response = await fetch('api/todos');
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || '獲取待辦事項失敗');
      }

      const data = await response.json();
      todos = data.items || [];
      renderTodos();
    } catch (error) {
      showError(error.message);
    }
  }

  // 綁定事件處理
  addBtn.addEventListener('click', addTodo);

  todoInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      addTodo();
    }
  });

  // 初始化應用程式
  fetchTodos();
});

